<?php
 namespace Pterodactyl\Services\Dezerx\Drive; use Ramsey\Uuid\Uuid; use Carbon\CarbonImmutable; use Pterodactyl\Models\Backup; use Pterodactyl\Models\Server; use Illuminate\Database\ConnectionInterface; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Extensions\Backups\BackupManager; use Pterodactyl\Repositories\Eloquent\BackupRepository; use Pterodactyl\Repositories\Wings\DaemonBackupRepository; use Symfony\Component\HttpKernel\Exception\TooManyRequestsHttpException; class DriveBackups { public function __construct( private BackupRepository $repository, private ConnectionInterface $connection, private DaemonBackupRepository $daemonBackupRepository, private BackupManager $backupManager, ) { } public function take(Server $server, string $name): Backup { $this->assertNotThrottled($server); return $this->connection->transaction(function () use ($server, $name) { $backup = $this->repository->create([ 'server_id' => $server->id, 'uuid' => Uuid::uuid4()->toString(), 'name' => $name, 'ignored_files' => [], 'disk' => $this->backupManager->getDefaultAdapter(), 'is_locked' => false, ], true, true); if (! $backup instanceof Backup) { throw new DisplayException('The panel could not record a new backup for this server.'); } $this->daemonBackupRepository->setServer($server) ->setBackupAdapter($this->backupManager->getDefaultAdapter()) ->backup($backup); return $backup; }); } public function overLimit(Server $server): bool { return $server->backup_limit < 1 || $this->repository->getNonFailedBackups($server)->count() > $server->backup_limit; } private function assertNotThrottled(Server $server): void { $limit = (int) config('backups.throttles.limit'); $period = (int) config('backups.throttles.period'); if ($period <= 0) { return; } $previous = $this->repository->getBackupsGeneratedDuringTimespan($server->id, $period); if ($previous->count() < $limit) { return; } $retry = (int) CarbonImmutable::now()->diffInSeconds($previous->last()->created_at->addSeconds($period)); throw new TooManyRequestsHttpException( $retry, sprintf( 'This server has taken %d backups in the last %d seconds, which is all the panel allows. Try again in %d seconds.', $limit, $period, max(1, $retry), ), ); } } 